"""First jury phase and preparation; September 2026 evidentiary distinction."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
THEME='https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/2026/16092026-Terceira-Secao-fixa-teses-repetitivas-sobre-uso-de-provas-do-inquerito-e-validade-do-testemunho-indireto-na.aspx'
STF='https://portal.stf.jus.br/processos/listarProcessos.asp?classe=ADPF&numeroProcesso=395'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(406,'Na primeira fase do júri, recebida acusação, há citação para resposta escrita em dez dias.', ['Prazo desde efetivo cumprimento do mandado; em citação inválida/edital, comparecimento do acusado ou defensor constituído.', 'Acusação arrola até oito na denúncia/queixa.', 'Defesa pode apresentar preliminares, documentos, provas e até oito testemunhas qualificadas.'], 'Não confundir oito testemunhas desta fase com cinco para plenário.', 'Defesa responde após citação efetiva e indica rol pertinente à primeira fase.', 'No preparo do plenário o limite é o do art. 422, não oito por repetição automática.', ['Primeira fase permite até oito no rol de defesa? Sim.', 'Cumprimento do mandado importa no início do prazo? Sim.'], 'Resposta no júri','Defesa técnica inicial do procedimento bifásico.')
add(407,'Exceções na primeira fase do júri seguem processamento apartado, conforme arts. 95–112.', ['Separar incidente e mérito da imputação.', 'Aplicar requisitos da exceção pertinente.'], 'Preliminar não vira automaticamente exceção com procedimento próprio sem identificar sua natureza.', 'Suspeição é processada pelo incidente adequado.', 'Argumento de mérito sobre autoria continua defesa da imputação, não exceção genérica.', ['As exceções seguem em apartado? Sim.', 'Toda tese de mérito é exceção? Não.'], 'Incidente apartado','Processamento separado da questão específica.')
add(408,'Sem resposta no prazo, juiz nomeia defensor com vista para oferecê-la em até dez dias.', ['Não dispensar resposta técnica por inércia pessoal.', 'Assegurar acesso efetivo aos autos.'], 'Silêncio do acusado não autoriza seguir sem defesa nem presumir culpa.', 'Após falta de resposta, defensor nomeado recebe vista e prazo.', 'Nomear sem disponibilizar autos não assegura preparação efetiva.', ['Inércia elimina defesa técnica? Não.', 'Nomeado recebe vista dos autos? Sim.'], 'Garantia de resposta','Defesa técnica preservada diante da omissão.')
add(409,'Após resposta, MP ou querelante é ouvido sobre preliminares e documentos em cinco dias.', ['Objeto específico: questões e documentos defensivos.', 'Não confundir com prazo de dez dias da resposta.'], 'Prazo dessa manifestação não substitui instrução nem resposta inicial.', 'Defesa junta documento relevante e acusação tem oportunidade de manifestação.', 'Sem documento ou preliminar controvertida, não inventar conteúdo acusatório novo pelo artigo.', ['Prazo desta manifestação é cinco dias? Sim.', 'É a resposta inicial do acusado? Não.'], 'Contraditório sobre a resposta','Manifestação da acusação sobre pontos defensivos.')
add(410,'Juiz determina testemunhas e diligências requeridas pelas partes no prazo máximo legal de dez dias.', ['Preparação da instrução da primeira fase.', 'Examinar pertinência e providências de intimação.'], 'Não confundir dez dias deste ato preparatório com noventa de conclusão da fase.', 'Juízo organiza produção da prova requerida após as manifestações.', 'Requerimento sem pertinência não elimina controle judicial fundamentado.', ['Este prazo é o de conclusão de toda a fase? Não.', 'Há providências de produção de prova? Sim.'], 'Preparação probatória','Organização das diligências e oitivas.')
add(411,'Audiência da primeira fase reúne prova, interrogatório ao final e debates, com decisão imediata ou em dez dias.', ['Ofendido se possível; testemunhas acusação e defesa; demais provas; acusado.', 'Peritos: requerimento prévio e deferimento.', 'Pode haver mutatio conforme art. 384.', 'Vinte minutos, prorrogáveis por dez; tempo individual de acusação e defesa por acusado.', 'Assistente: dez minutos e igual acréscimo defensivo.', 'Adiamento só por prova imprescindível; testemunha presente é ouvida, observada ordem.'], 'Condução referida no §7º não autoriza obrigar réu a interrogatório: integrar ADPFs 395/444.', 'Testemunha presente depõe respeitada ordem e acusado é interrogado após prova.', 'Ausência do acusado não legitima conduzi-lo coercitivamente para interrogatório.', ['Tempo individual inclui acusação e defesa por acusado? Sim.', '§7º autoriza forçar interrogatório do réu? Não.'], 'Instrução preliminar do júri','Prova e debates antes da decisão de admissibilidade.',[STF])
add(412,'A primeira fase do procedimento do júri tem prazo máximo legal de noventa dias.', ['Não confundir com sessenta da audiência ordinária.', 'Excesso deve ser analisado concretamente, sem automatismo isolado.'], 'Noventa dias não é duração máxima de todo o procedimento até veredito nem causa automática de absolvição.', 'Acompanhamento verifica prazo da fase e justificativas de demora.', 'Necessidade concreta de diligência exige análise, não declaração mecânica de culpa ou inocência por calendário.', ['Prazo é de noventa dias? Sim.', 'Abrange necessariamente julgamento final em plenário? Não.'], 'Prazo da primeira fase','Referência temporal para conclusão da instrução preliminar.')
add(413,'Pronúncia exige materialidade e indícios suficientes de autoria/participação, com motivação limitada e decisão cautelar própria.', ['Indicar enquadramento, qualificadoras e aumentos sem linguagem de condenação.', 'Tema 1260/STJ, setembro de 2026: inquérito sozinho não basta, ressalvadas provas cautelares, irrepetíveis e antecipadas.', 'Relato indireto é admissível, mas isolado é insuficiente; relato qualificado em intimidação objetiva exige controle estrito e defesa.', 'Fiança e cautelares dependem de requisitos específicos, não automatismo.'], 'Não substituir suporte probatório por in dubio pro societate nem tratar pronúncia como condenação.', 'Prova judicial consistente de materialidade e indícios autoriza exame de submissão ao júri.', 'Boato isolado não basta; intimidação comprovada exige avaliar qualificação do relato e garantias, não presumir exceção.', ['Pronúncia é condenação? Não.', 'Ouvir dizer isolado basta? Não.'], 'Pronúncia','Juízo fundamentado de admissibilidade da acusação para plenário.',[THEME])
add(414,'Impronúncia ocorre sem convencimento sobre materialidade ou indícios suficientes de autoria/participação.', ['Fundamentação necessária.', 'Nova acusação possível com prova nova enquanto punibilidade não extinta.', 'Não equivale a condenação nem absolvição sumária de mérito.'], 'Não reenviar a mesma acusação sem prova nova para contornar insuficiência reconhecida.', 'Indícios insuficientes resultam em impronúncia.', 'Prova realmente nova pode permitir nova acusação antes de extinta punibilidade.', ['Prova nova pode permitir nova denúncia? Sim, nas condições legais.', 'Impronúncia equivale a condenação? Não.'], 'Impronúncia','Inadmissibilidade da acusação por insuficiência dos requisitos.')
add(415,'Absolvição sumária no júri exige hipótese demonstrada: inexistência, não autoria, atipicidade ou exclusão/isenção.', ['Inexistência e não participação devem estar provadas.', 'Inimputabilidade não permite aplicar inciso IV salvo se única tese defensiva.', 'Distinguir hipótese provada de simples insuficiência que leva à impronúncia.'], 'Não ignorar defesa de inocência para impor medida de segurança por inimputabilidade quando não é a única tese.', 'Prova demonstra acusado não participou: absolvição sumária pertinente.', 'Inimputabilidade e negativa de autoria coexistem: respeitar ressalva do parágrafo único.', ['Inimputabilidade sempre permite absolvição sumária? Não.', 'Ausência de prova é igual a não autoria provada? Não.'], 'Absolvição sumária no júri','Decisão de mérito nas hipóteses demonstradas.')
add(416,'Impronúncia e absolvição sumária são impugnáveis por apelação.', ['Não confundir com recurso da pronúncia.', 'Identificar decisão recorrida antes de escolher instrumento.'], 'Semelhança de nomes não torna idêntica a via recursal de todas as decisões da fase.', 'Acusação recorre por apelação de absolvição sumária.', 'Pronúncia exige examinar recurso em sentido estrito do art. 581, IV.', ['Impronúncia admite apelação? Sim.', 'Pronúncia usa necessariamente mesma via? Não.'], 'Apelação da fase preliminar','Recurso previsto para as duas decisões do artigo.')
add(417,'Indícios de participação de pessoa não acusada levam à remessa ao MP por quinze dias ao pronunciar ou impronunciar.', ['Não incluir acusado novo por iniciativa condenatória do juiz.', 'Aplicar separação do art. 80 no que couber.'], 'Indício sobre terceiro não dispensa acusação regular, citação e defesa.', 'Prova aponta terceiro e autos retornam ao MP para providências pertinentes.', 'Juiz não condena terceiro estranho ao processo apenas por constar depoimento.', ['Prazo de remessa é quinze dias? Sim.', 'Terceiro pode ser condenado sem acusação regular? Não.'], 'Participante não acusado','Indícios que exigem atuação acusatória e garantias.')
add(418,'Juiz pode dar definição jurídica diversa ao fato na decisão da fase, inclusive com consequência penal mais grave.', ['Classificação jurídica não autoriza criar fatos.', 'Novo elemento ausente da acusação exige regime pertinente de aditamento.'], 'Integrar correlação e art. 384; não ocultar mudança factual sob rótulo de classificação.', 'Mesma narrativa recebe enquadramento juridicamente adequado.', 'Circunstância nova não descrita demanda contraditório e procedimento próprio.', ['Artigo permite criar fato acusatório? Não.', 'Nova definição pode ser mais grave? Sim, respeitados limites.'], 'Reclassificação no júri','Definição jurídica diversa dentro dos limites da imputação.')
add(419,'Reconhecido crime fora da competência do júri e sem competência do juiz, autos seguem ao juízo competente.', ['Acusado preso fica à disposição do novo juízo.', 'Não é absolvição automática.', 'Custódia exige fundamentos atuais próprios.'], 'Remessa não legitima manutenção eterna da prisão nem condena pelo novo crime.', 'Juízo reconhece crime não doloso contra vida e remete ao competente.', 'Novo órgão avalia processo e legalidade da cautelar, não presume sentença já proferida.', ['Desclassificação significa absolvição sempre? Não.', 'Preso fica à disposição do novo juízo? Sim.'], 'Desclassificação e remessa','Mudança da competência por definição do crime.')
add(420,'Pronúncia é intimada pessoalmente ao acusado, defensor nomeado e MP; demais sujeitos seguem publicação do regime indicado.', ['Constituído, querelante e assistente: art. 370, §1º.', 'Acusado solto não encontrado: edital.', 'Distinguir pronúncia de intimação da sentença final.'], 'Edital do solto não localizado não dispensa a ciência regular da defesa.', 'Defensor nomeado recebe ciência pessoal da pronúncia.', 'Acusado solto não localizado é intimado por edital na hipótese própria.', ['Nomeado recebe intimação pessoal? Sim.', 'Solto não encontrado tem hipótese de edital? Sim.'], 'Ciência da pronúncia','Comunicação diferenciada conforme sujeito processual.')
add(421,'Após preclusão da pronúncia, autos vão ao presidente do júri; circunstância superveniente relevante pode alterar classificação.', ['Superveniência leva à remessa ao MP e posterior decisão judicial.', 'Não confundir preclusão da fase com condenação definitiva.'], 'Juiz não ignora mudança superveniente nem transforma encaminhamento em veredito.', 'Pronúncia estabilizada segue ao preparo de plenário.', 'Circunstância nova que altera classificação demanda providência acusatória e decisão apropriada.', ['Preclusão da pronúncia é condenação final? Não.', 'Circunstância superveniente pode exigir remessa ao MP? Sim.'], 'Preclusão da pronúncia','Estabilização da decisão para prosseguimento, com ressalva legal.')
add(422,'No preparo do plenário, acusação e defesa têm cinco dias para rol de até cinco testemunhas, documentos e diligências.', ['MP ou querelante no caso de queixa e defensor são intimados.', 'Rol desta etapa é distinto do inicial de oito.', 'Verificar requisitos adicionais de comparecimento no plenário.'], 'Não usar limite inicial de oito para testemunhas que deporão no plenário.', 'Defesa indica cinco testemunhas de plenário no prazo.', 'Testemunha essencial exige também observar providências específicas de intimação, não só nome no rol.', ['Rol de plenário tem até cinco? Sim.', 'Prazo deste preparo é dez dias? Não, cinco.'], 'Rol de plenário','Indicação específica para julgamento perante jurados.')
add(423,'Presidente decide pedidos, promove diligências úteis e elabora relatório sucinto para pautar julgamento.', ['Sanar nulidade ou esclarecer fato pertinente.', 'Relatório não é antecipação do veredito.', 'Providências devem respeitar contraditório.'], 'Resumo deve informar o processo sem afirmar culpa como decisão já tomada.', 'Juiz organiza prova e relata andamento de forma sucinta.', 'Diligência relevante não autoriza opinião condenatória no relatório aos jurados.', ['Relatório deve antecipar condenação? Não.', 'Pode haver diligência para sanar nulidade? Sim.'], 'Preparo pelo presidente','Organização do julgamento e relatório processual.')
add(424,'Se organização judiciária local atribui preparo a outro juiz, processo preparado é remetido até cinco dias antes do sorteio do art. 433.', ['Também remeter os preparados até encerramento da reunião para julgamento.', 'Distinguir preparo e presidência conforme lei local.'], 'Os cinco dias são anteriores ao sorteio referido, não prazo universal contado do veredito.', 'Juiz responsável envia processo preparado em tempo para organização do júri.', 'Competência do preparo depende da lei local, não sempre do mesmo órgão.', ['Marco é o sorteio do art. 433? Sim.', 'A lei local pode separar preparo e presidência? Sim.'], 'Remessa do processo preparado','Encaminhamento organizado segundo atribuições locais.')
assert len(rows)==19
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'jury first-phase units reviewed')
